package cn.blockforge.generated.generatedmod;

import cn.blockforge.generated.generatedmod.alchemy.batch.*;
import cn.blockforge.generated.generatedmod.alchemy.effects.*;
import cn.blockforge.generated.generatedmod.alchemy.research.*;
import cn.blockforge.generated.generatedmod.alchemy.simulation.*;
import cn.blockforge.generated.generatedmod.plants.*;
import cn.blockforge.generated.generatedmod.progression.PlayerCrafts;
import cn.blockforge.generated.generatedmod.storage.BagInventory;
import net.minecraft.gametest.framework.*;
import net.minecraft.nbt.*;
import net.minecraft.world.item.*;
import net.minecraft.world.level.GameType;
import net.minecraftforge.gametest.*;
import java.util.*;
import static cn.blockforge.generated.generatedmod.alchemy.simulation.AlchemySimulation.*;

@GameTestHolder("wuxingxiantu_entry") @PrefixGameTestTemplate(false)
public final class AlchemyCertificationGameTests {
    private static CompoundTag root(V5BatchGameTests.Fixture f){
        var d=ResearchInferenceGameTests.terminal(f,100,4,true);var m=ResearchInferenceGameTests.educate(f.player());
        var solver=new ResearchInference(ResearchInference.goal(PillSnapshot.read(d.getCompound("PillResult"))),ResearchEvidence.history(f.player(),m.known(f.player())));
        return ResearchLineage.save(f.player(),solver,solver.candidate(0),List.of(),m);
    }
    private static CompoundTag trial(V5BatchGameTests.Fixture f,boolean success,int years,ItemStack reuse,Long seed){
        return trial(f,success,years,reuse,seed,true);
    }
    private static CompoundTag trial(V5BatchGameTests.Fixture f,boolean success,int years,ItemStack reuse,Long seed,boolean vary){
        var herb=reuse==null?new ItemStack(SpiritPlantRegistry.SPIRIT_SPROUT_GRASS_ITEM.get(),4):reuse.copyWithCount(4);HerbAge.setYears(herb,years);if(reuse==null)HerbAge.newAcquisitionLot(herb);f.furnace().setItem(0,herb);
        var d=V5Batch.prepare(f.furnace(),f.player());var profile=V5Batch.profile(d.getString("Profile"),d.getInt("Burn"));var initial=V5Batch.core(d);
        if(seed!=null){var s=AlchemySimulation.begin(profile.rules(),d.getUUID("Id").toString(),initial.stocks(),0,initial.referenceMass(),seed,initial.environment());d.putByteArray("Core",SimulationSnapshotCodec.encodeServerSnapshot(profile.rules(),s));}
        if(vary){var env=new TreeMap<>(V5Batch.core(d).environment());env.put("moon_phase",(long)(AlchemyCertification.protocols(f.player()).isEmpty()?0:protocol(f).getList("Trials",Tag.TAG_COMPOUND).size()%2));var old=V5Batch.core(d);var s=AlchemySimulation.begin(profile.rules(),d.getUUID("Id").toString(),old.stocks(),0,old.referenceMass(),old.seed(),env);d.putByteArray("Core",SimulationSnapshotCodec.encodeServerSnapshot(profile.rules(),s));d.put("ResearchStart",ResearchEvidence.start(env,0));}
        var journal=new BatchJournal(f.player().server);journal.write(d);initial=V5Batch.core(d);
        var s=AlchemySimulation.begin(profile.rules(),d.getUUID("Id").toString(),success?Map.of("extract_mu",80L):Map.of("herb_inert",80L),0,80,initial.seed(),initial.environment());
        s=new Snapshot(s.batchId(),s.rulesHash(),0,SimulationRules.Phase.COOL,Status.FINISHED,"",s.stocks(),0,0,s.referenceMass(),s.seed(),s.environment(),s.draws(),s.holds(),s.lastSequence(),s.operations(),s.ledger());
        d.putByteArray("Core",SimulationSnapshotCodec.encodeServerSnapshot(profile.rules(),s));d=V5Batch.seal(d);journal.write(d);return d;
    }
    private static CompoundTag protocol(V5BatchGameTests.Fixture f){return AlchemyCertification.protocols(f.player()).getCompound(0);}
    private static void freeze(V5BatchGameTests.Fixture f,CompoundTag root,GameTestHelper h){f.player().join();f.player().setGameMode(GameType.SURVIVAL);h.assertTrue(AlchemyCertification.freeze(f.player(),root.getString("Id"),1),"Cannot freeze survival holdout");}
    @GameTest(template="empty") public static void wilsonRequiresEvidenceBeyondRawEightyPercent(GameTestHelper h){double z=1.959963984540054;h.assertTrue(AlchemyCertification.lower(24,30,z)<.8&&AlchemyCertification.lower(28,30,z)<.8&&AlchemyCertification.lower(29,30,z)>=.8&&AlchemyCertification.lower(30,30,z)>=.8,"Confidence bound reduced to raw percentage");boolean rejected=false;try{AlchemyCertification.lower(31,30,z);}catch(IllegalArgumentException expected){rejected=true;}h.assertTrue(rejected,"Impossible sample accepted");h.succeed();}
    @GameTest(template="empty",timeoutTicks=200) public static void thirtyFutureTrialsCertifyAndPromoteWithoutXp(GameTestHelper h){try(var f=V5BatchGameTests.setup(h)){var root=root(f);freeze(f,root,h);for(int i=0;i<30;i++)trial(f,true,100,null,null);var n=protocol(f);var stats=AlchemyCertification.statistics(n);h.assertTrue(stats.getInt("Pass")==30&&stats.getInt("Pending")==0&&stats.getInt("Lots")==30,"Future trials not independent or not measured: "+stats);h.assertTrue(AlchemyCertification.issue(f.player(),n.getUUID("Id")),"Perfect holdout did not certify");var row=PlayerCrafts.get(f.player().server).profession(f.player().getUUID(),"alchemy");row.putBoolean("Learned",true);String result=AlchemyCertification.promote(f.player());h.assertTrue(AlchemyCertification.certifiedRank(f.player())==1&&row.getInt("Xp")==0,"Formal rank still depends on legacy XP: "+result);h.assertTrue(!AlchemyCertification.issue(f.player(),n.getUUID("Id")),"Certificate replay mutated state");h.assertTrue(new BatchJournal(f.player().server).certification(f.player().getUUID()).getInt("CertifiedRank")==1,"Rank not durable");}h.succeed();}
    @GameTest(template="empty",timeoutTicks=200) public static void everyFailureCountsAndCopyingRevisionCannotResetHoldout(GameTestHelper h){try(var f=V5BatchGameTests.setup(h)){var root=root(f);freeze(f,root,h);for(int i=0;i<30;i++)trial(f,i<24,100,null,null);var n=protocol(f);h.assertTrue(!AlchemyCertification.issue(f.player(),n.getUUID("Id"))&&protocol(f).getString("State").equals("FAILED")&&AlchemyCertification.statistics(protocol(f)).getInt("Fail")==6,"Failures discarded or 24/30 certified");h.assertTrue(!AlchemyCertification.freeze(f.player(),root.getString("Id"),1),"Same frozen content reset after failure");trial(f,true,100,null,null);h.assertTrue(protocol(f).getList("Trials",Tag.TAG_COMPOUND).size()==30,"Thirty-first result replaced failure");}h.succeed();}
    @GameTest(template="empty") public static void repeatedSeedsOldLotsAndChangedPlanAreNotIndependentSuccesses(GameTestHelper h){try(var f=V5BatchGameTests.setup(h)){var root=root(f);var old=new ItemStack(SpiritPlantRegistry.SPIRIT_SPROUT_GRASS_ITEM.get(),4);HerbAge.setYears(old,100);HerbAge.newAcquisitionLot(old);trial(f,true,100,old,null);freeze(f,root,h);var a=trial(f,true,100,null,null);trial(f,true,100,null,V5Batch.core(a).seed());trial(f,true,100,old,null);trial(f,true,101,null,null);var trials=protocol(f).getList("Trials",Tag.TAG_COMPOUND);h.assertTrue(trials.size()==4&&trials.getCompound(0).getString("State").equals("PASS")&&trials.getCompound(1).getString("Reason").equals("REUSED_SEED")&&trials.getCompound(2).getString("Reason").equals("MATERIAL_LOT")&&trials.getCompound(3).getString("Reason").equals("OUTSIDE_FROZEN_SCOPE"),"Independence or frozen plan bypassed: "+trials);var disk=new BatchJournal(f.player().server).certification(f.player().getUUID());h.assertTrue(disk.getList("Protocols",Tag.TAG_COMPOUND).equals(AlchemyCertification.protocols(f.player())),"Cached ledger differs from durable data");}h.succeed();}
    @GameTest(template="empty") public static void creativeFreezeAndResearchWithoutControlledEvidenceAreRejected(GameTestHelper h){try(var f=V5BatchGameTests.setup(h)){var root=root(f);h.assertTrue(!AlchemyCertification.freeze(f.player(),root.getString("Id"),1),"Creative certification accepted");f.player().setGameMode(GameType.SURVIVAL);h.assertTrue(!AlchemyCertification.freeze(f.player(),root.getString("Id"),0),"Fixed recipe repetitions became independent research");h.assertTrue(AlchemyCertification.freeze(f.player(),root.getString("Id"),1)&&!AlchemyCertification.freeze(f.player(),root.getString("Id"),2),"Overlapping protocol accepted");}h.succeed();}
    @GameTest(template="empty") public static void storageBagMergesDisplayButNeverMintsOrMixesMaterialLots(GameTestHelper h){var bag=new BagInventory();var a=new ItemStack(SpiritPlantRegistry.SPIRIT_SPROUT_GRASS_ITEM.get(),3);HerbAge.setYears(a,100);HerbAge.newAcquisitionLot(a);var b=a.copyWithCount(5);b.getOrCreateTag().remove(HerbAge.LOT);HerbAge.newAcquisitionLot(b);UUID first=a.getTag().getUUID(HerbAge.LOT),second=b.getTag().getUUID(HerbAge.LOT);bag.insert(a);bag.insert(b);bag=BagInventory.load(bag.save());h.assertTrue(bag.entries.size()==1&&bag.entries.get(0).total()==8,"Lot metadata broke merged storage");var x=bag.entries.get(0).take(64);var y=bag.entries.get(0).take(64);h.assertTrue(x.getCount()==3&&y.getCount()==5&&x.getTag().getUUID(HerbAge.LOT).equals(first)&&y.getTag().getUUID(HerbAge.LOT).equals(second),"Withdrawal mixed or invented lots");var fake=y.copy();fake.getOrCreateTag().putUUID(HerbAge.LOT,UUID.randomUUID());h.assertTrue(bag.entries.get(0).takeMatching(fake,1).isEmpty(),"Target NBT forged an origin");h.succeed();}
    @GameTest(template="empty",timeoutTicks=200) public static void unresolvedOrLostCommitCannotBeReplacedByAChosenSuccess(GameTestHelper h){try(var f=V5BatchGameTests.setup(h)){var root=root(f);freeze(f,root,h);var ghost=V5Batch.prepare(f.furnace(),f.player());var journal=new BatchJournal(f.player().server);AlchemyCertification.reserve(f.player().server,journal,ghost);for(int i=0;i<29;i++)trial(f,true,100,null,null);var n=protocol(f);h.assertTrue(AlchemyCertification.statistics(n).getInt("Pending")==1,"Lost commit omitted from cohort");h.assertTrue(AlchemyCertification.issue(f.player(),n.getUUID("Id")),"29/30 lower bound should pass with lost commit counted as failure");var stats=AlchemyCertification.statistics(protocol(f));h.assertTrue(stats.getInt("Pass")==29&&stats.getInt("Fail")==1&&stats.getInt("Formed")==29&&protocol(f).getList("Trials",Tag.TAG_COMPOUND).getCompound(0).getString("Reason").equals("MISSING_COMMIT"),"Lost transaction replaced or omitted from reports");}h.succeed();}
    @GameTest(template="empty",timeoutTicks=200) public static void nineGradeNeedsSuccessfulEnvironmentVariationAndCannotSkipOfficialResearchRequirements(GameTestHelper h){try(var f=V5BatchGameTests.setup(h)){var saved=new CompoundTag();saved.putInt("Schema",1);saved.putUUID("Owner",f.player().getUUID());saved.putInt("CertifiedRank",8);new BatchJournal(f.player().server).certification(f.player().getUUID(),saved);var root=root(f);freeze(f,root,h);for(int i=0;i<30;i++)trial(f,true,100,null,null,false);var n=protocol(f);var stats=AlchemyCertification.statistics(n);h.assertTrue(n.getInt("Grade")==9&&stats.getInt("Pass")==30&&stats.getInt("Environments")==1,"High rank fixture not nine-grade or varied unexpectedly: "+stats);h.assertTrue(!AlchemyCertification.issue(f.player(),n.getUUID("Id")),"One environment was accepted for nine-grade validation");h.assertTrue(AlchemyCertification.certifiedRank(f.player())==8,"Failed holdout promoted rank");var row=PlayerCrafts.get(f.player().server).profession(f.player().getUUID(),"alchemy");row.putInt("AlchemyCertifiedRank",0);h.assertTrue(AlchemyCertification.certifiedRank(f.player())==8&&row.getInt("AlchemyCertifiedRank")==8&&row.getInt("Rank")>=7,"Durable certification not reconciled after stale profession save");}h.succeed();}
    @GameTest(template="empty") public static void anotherSeedDoesNotMakeTheSameHarvestAnIndependentLot(GameTestHelper h){try(var f=V5BatchGameTests.setup(h)){freeze(f,root(f),h);var first=trial(f,true,100,null,null);var material=ItemStack.of(first.getList("Materials",Tag.TAG_COMPOUND).getCompound(0));trial(f,true,100,material,null);var trials=protocol(f).getList("Trials",Tag.TAG_COMPOUND);h.assertTrue(trials.getCompound(0).getString("State").equals("PASS")&&trials.getCompound(1).getString("Reason").equals("MATERIAL_LOT"),"Splitting a holdout harvest minted independent observations");}h.succeed();}
    @GameTest(template="empty",timeoutTicks=200) public static void eightToNinePromotionRequiresEveryOfficialTypeAndOwnResearch(GameTestHelper h){
        // Authority fixtures test credential requirements; their 30 physical trials are covered separately.
        for(int missing=-1;missing<4;missing++)try(var f=V5BatchGameTests.setup(h)){var p=f.player();var ledger=new CompoundTag();ledger.putInt("Schema",1);ledger.putUUID("Owner",p.getUUID());ledger.putInt("CertifiedRank",8);var credentials=new ListTag();for(int kind=0;kind<4;kind++)if(kind!=missing){var n=new CompoundTag();n.putString("State","CERTIFIED");n.putInt("Grade",9);n.putInt("Kind",kind);n.putString("Context",ResearchEvidence.currentContext(p));n.put("Policy",AlchemyCertification.policy(p));credentials.add(n);}ledger.put("Protocols",credentials);new BatchJournal(p.server).certification(p.getUUID(),ledger);root(f);GeneratedMod.data(p).wuxingxiantu$setRealm(6);PlayerCrafts.get(p.server).profession(p.getUUID(),"alchemy").putBoolean("Learned",true);AlchemyCertification.promote(p);h.assertTrue(AlchemyCertification.certifiedRank(p)==(missing<0?9:8),"Missing official/research credential bypassed, kind="+missing);}
        h.succeed();
    }
}
